const sources = [
  { name: "OpenAI News", category: "AI", site: "openai.com/news" },
  { name: "Google AI Blog", category: "AI", site: "blog.google/technology/ai" },
  { name: "Microsoft AI Blog", category: "AI", site: "blogs.microsoft.com/ai" },
  { name: "NVIDIA AI Blog", category: "AI", site: "blogs.nvidia.com" },
  { name: "Hugging Face Blog", category: "AI", site: "huggingface.co/blog" },
  { name: "AWS Machine Learning Blog", category: "AI", site: "aws.amazon.com/blogs/machine-learning" },
  { name: "MIT News AI", category: "AI", site: "news.mit.edu" },
  { name: "Microsoft Power BI Blog", category: "BI", site: "powerbi.microsoft.com/blog" },
  { name: "Tableau Blog", category: "BI", site: "tableau.com/blog" },
  { name: "Qlik Blog", category: "BI", site: "qlik.com/blog" },
  { name: "ThoughtSpot Data Trends", category: "BI", site: "thoughtspot.com/data-trends" },
  { name: "dbt Labs Blog", category: "BI", site: "getdbt.com/blog" }
];
const recipients = ["primary.recipient@example.com", "secondary.recipient@example.com"];
const llm = { baseUrl: "http://ollama:11434", model: "llama3.2:3b" };
const validSources = sources.filter(s => s.name && s.category && /^[a-z0-9.-]+(?:\/[a-z0-9._~!$&'()*+,;=:@%/-]*)?$/i.test(s.site || ""));
const validRecipients = [...new Set(recipients.map(String).map(e => e.trim()).filter(e => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)))];
if (validSources.length < 10) throw new Error("Configure at least 10 valid sources.");
if (!validRecipients.length) throw new Error("Configure at least one valid email recipient.");
const query = "(" + validSources.map(s => "site:" + s.site).join(" OR ") + ") (AI OR analytics OR \"business intelligence\")";
const feedUrl = "https://news.google.com/rss/search?q=" + encodeURIComponent(query) + "&hl=en-US&gl=US&ceid=US%3Aen";
return [{json:{sources:validSources,sourceNames:validSources.map(s => s.name),feedUrl,recipients:validRecipients,llm}}];

