const news=$input.all().map(i=>i.json).filter(a=>{const d=Date.parse(a.isoDate||a.pubDate||"");return !Number.isFinite(d)||d>=cutoff;}).filter(a=>{const k=String(a.link||a.guid||a.title||"").trim();if(!k||seen.has(k))return false;seen.add(k);return true;}).sort((a,b)=>Date.parse(b.isoDate||b.pubDate||0)-Date.parse(a.isoDate||a.pubDate||0)).slice(0,12).map((a,i)=>({id:i+1,title:String(a.title||"").trim(),description:String(a.contentSnippet||a.content||a.description||"").replace(/<[^>]*>/g," ").replace(/\s+/g," ").trim(),link:a.link||a.guid||"",publishedAt:a.isoDate||a.pubDate||""}));
const sourceText=news.length?news.map(a=>"[N"+a.id+"] "+a.title+"
Date: "+a.publishedAt+"
Description: "+a.description+"
Link: "+a.link).join("

"):"No recent articles were found.";
const prompt="Prepare a professional executive briefing in European Portuguese, based exclusively on the supplied articles. The audience consists of technology, data and business decision-makers. Organize it into Artificial Intelligence and Business Intelligence & Analytics. Start with a short executive summary. Select the most relevant developments, including a factual summary, business impact and clickable source link. End with three trends to watch. Do not invent information. Respond only with a valid HTML fragment using h2, h3, p, ul, li, strong, em, a and hr.

ARTICLES:
"+sourceText;
return [{json:{articleCount:news.length,recipients:config.recipients,sourceNames:config.sourceNames,articles:news,prompt}}];

