let content=String($json?.message?.content||"").trim().replace(/<\/?(?:html|head|body)[^>]*>/gi,"").replace(/<script[\s\S]*?<\/script>/gi,"").replace(/<style[\s\S]*?<\/style>/gi,""); if(!content)content="<p>The briefing could not be generated.</p>";
